/* Generated by Trae Work */
/* 刷题与错题本：仅显示来源自带的答案，不生成解析 */
"use strict";
(function () {
  document.addEventListener("DOMContentLoaded", () => {
    const SRC = SITE_DATA.quiz_source;
    const answers = Store.get("quiz_answers", {});   // {qid: {picked, correct}}
    const wrong = Store.get("wrong_book", {});       // {qid: {count, last_review, mastered}}
    let filter = "all";

    /* 来源说明 */
    document.getElementById("quiz-source-info").innerHTML = `
      <h3>${SRC.paper_title} <span class="badge kaoyan">kaoyan</span></h3>
      <p class="muted" style="margin-top:4px;">来源：${SRC.source_platform} · 来源类型：${SRC.source_type}（重排版，存在少量文字识别错误风险） · 收录快照：${SRC.crawled_at}</p>
      <p class="muted" style="margin-top:4px;">答案来源：<a href="${SRC.answer_url}" target="_blank" rel="noopener">answers/2023-answer.pdf（仓库内参考答案表）</a>。${SRC.note}</p>
      <p class="src" style="margin-top:6px;">试卷 URL：<a href="${SRC.paper_url}" target="_blank" rel="noopener">${SRC.paper_url}</a></p>`;

    function renderQuestions() {
      const list = document.getElementById("quiz-list");
      const qs = SITE_DATA.quiz.filter(q => filter === "all" || q.subject === filter);
      list.innerHTML = "";
      if (qs.length === 0) {
        list.innerHTML = `<div class="notice empty">该科目暂无已收录题目。</div>`;
        return;
      }
      qs.forEach(q => {
        const rec = answers[q.id];
        const card = h("div", { class: "q-card" });
        card.innerHTML = `
          <div class="q-meta"><span class="badge kaoyan">kaoyan</span><span class="badge code">${subjectName(q.subject)}</span><span class="badge code">第 ${q.qno} 题 · 2 分</span></div>
          <div class="q-stem">${q.stem}</div>
          <div class="q-opts">${q.options.map((o, i) => {
            const L = "ABCD"[i];
            let cls = "q-opt";
            if (rec) {
              if (L === q.answer) cls += " right";
              else if (L === rec.picked) cls += " wrong";
            } else if (rec === null && L === (Store.get("quiz_pick_" + q.id, null))) cls += " sel";
            return `<div class="${cls}" data-qid="${q.id}" data-opt="${L}">${L}. ${o}</div>`;
          }).join("")}</div>
          <div class="q-ans ${q.answer ? "has-ans" : "no-ans"}" style="display:${rec ? "block" : "none"};">
            ${q.answer
              ? `正确答案：${q.answer}${rec && rec.correct ? "（回答正确）" : rec ? "（回答错误）" : ""}　答案来自来源参考答案表。`
              : "来源未提供答案"}
          </div>
          <div class="q-actions">
            <button class="btn small ghost" data-src="${q.id}">查看来源</button>
          </div>`;
        /* 选择交互 */
        card.querySelectorAll(".q-opt").forEach(opt => {
          opt.addEventListener("click", () => {
            if (answers[q.id]) return;
            const picked = opt.dataset.opt;
            const correct = picked === q.answer;
            answers[q.id] = { picked, correct };
            Store.set("quiz_answers", answers);
            if (!correct) {
              wrong[q.id] = {
                count: (wrong[q.id] && wrong[q.id].count || 0) + 1,
                last_review: fmtDate(new Date()),
                mastered: false,
                track: q.track, subject: q.subject
              };
              Store.set("wrong_book", wrong);
            }
            renderQuestions();
            renderWrongBook();
          });
        });
        card.querySelector("[data-src]").addEventListener("click", () => {
          window.open(SRC.paper_url, "_blank", "noopener");
        });
        list.appendChild(card);
      });
    }

    function renderWrongBook() {
      const root = document.getElementById("wrong-book");
      const entries = Object.entries(wrong).filter(([id, w]) => !w.mastered);
      if (entries.length === 0) {
        root.innerHTML = `<div class="notice empty">错题本为空。答错的题会自动按 track 与科目归类到这里。</div>`;
        return;
      }
      root.innerHTML = "";
      entries.forEach(([id, w]) => {
        const q = SITE_DATA.quiz.find(x => x.id === id);
        if (!q) return;
        const d = h("div", { class: "wrong-item" });
        d.innerHTML = `
          <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
            <span class="badge ${w.track}">${w.track === "zikao" ? "自考" : "考研"}</span>
            <span class="badge code">${subjectName(w.subject)}</span>
            <strong style="font-size:13.5px;">错误 ${w.count} 次 · 最后复习 ${w.last_review}</strong>
          </div>
          <p style="margin-top:6px;">${q.stem}</p>
          <p style="margin-top:4px;font-size:13.5px;">你的答案：<strong style="color:#e30000">${answers[id] ? answers[id].picked : "—"}</strong>
            ${q.answer ? `　正确答案：<strong style="color:var(--zikao-ink)">${q.answer}</strong>（来源答案表）` : "　来源未提供答案"}</p>
          <div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;">
            <a class="btn small ghost" href="${SRC.paper_url}" target="_blank" rel="noopener">题目原文/来源</a>
            <button class="btn small" data-master="${id}">标记已掌握（移出）</button>
          </div>`;
        d.querySelector("[data-master]").addEventListener("click", () => {
          wrong[id].mastered = true;
          Store.set("wrong_book", wrong);
          renderWrongBook();
        });
        root.appendChild(d);
      });
    }

    document.getElementById("quiz-filter").addEventListener("click", e => {
      const b = e.target.closest("button[data-subject]");
      if (!b) return;
      filter = b.dataset.subject;
      document.querySelectorAll("#quiz-filter button").forEach(x => x.classList.toggle("active", x === b));
      renderQuestions();
    });
    document.querySelector('#quiz-filter [data-subject="all"]').classList.add("active");
    renderQuestions();
    renderWrongBook();
  });
})();
